<template>
  <main class="clocktower-page">
    <header><p class="page-eyebrow">Saujana’s nights in Ravenswood Bluff</p><h1>Blood on the Clocktower</h1><p class="intro">Good games, impossible choices and the moment the town finds out.</p></header>
    <section class="next-night"><div><p class="eyebrow">The next gathering</p><h2>{{ nextNight ? formatDate(nextNight.session_date) : 'The town will meet again' }}</h2><p>{{ nextNight?.session_time }}<template v-if="nextNight?.venue"> · {{ nextNight.venue }}</template></p><p>{{ nextNight?.first_timer_note || 'New to Clocktower? Come along. We’ll walk you through your first game.' }}</p></div><a class="primary-link" :href="nextNight?.signup_url || 'https://wa.me/saujanabgc'" target="_blank" rel="noopener noreferrer">{{ nextNight?.signup_url ? 'Save your place ↗' : 'Ask about the next game ↗' }}</a></section>
    <section v-if="featured" class="featured"><img v-if="cover(featured)" :src="photoUrls[cover(featured)]" alt="A moment from a Saujana Clocktower gathering"><div><p class="eyebrow">A moment from the last gathering</p><h2>{{ featured.teaser || 'The final reveal' }}</h2><p>{{ formatDate(featured.session_date) }} · {{ featured.venue }}</p><details><summary>Reveal Mika’s retelling</summary><p>{{ featured.recap }}</p></details><button class="share-button" type="button" @click="shareSession(featured)">Copy recap link</button><p v-if="shareNotice" role="status">{{ shareNotice }}</p></div></section>
    <section v-if="!loading && !error" class="stats"><h2>Stories from the circle</h2><div class="stat-row"><div><strong>{{ statistics.sessions }}</strong><span>gatherings</span></div><div><strong>{{ statistics.games }}</strong><span>games played</span></div><div><strong>{{ statistics.scripts }}</strong><span>scripts explored</span></div></div></section>
    <section class="archive"><p class="eyebrow">Past gatherings</p><h2>Every town has a story</h2><p v-if="error" role="alert">{{ error }} <button type="button" @click="loadArchive">Try again</button></p><p v-else-if="loading">Opening the grimoire…</p><p v-else-if="!pastSessions.length">No past sessions logged yet. The first story is still to come.</p><article v-for="session in pastSessions" :id="'session-' + session.id" :key="session.id" class="session-card"><h3>{{ formatDate(session.session_date) }}</h3><p>{{ session.venue || 'Saujana gathering' }} · {{ session.games.length }} game{{ session.games.length === 1 ? '' : 's' }}</p><details v-if="session.recap"><summary>Reveal Mika’s retelling</summary><p>{{ session.recap }}</p></details><button class="share-button" type="button" @click="shareSession(session)">Copy gathering link</button><div class="game-grid"><details v-for="(game, index) in session.games || []" :key="game.id || index"><summary>{{ game.script || 'Custom script' }}</summary><p v-if="game.outcome"><strong>{{ game.outcome }}</strong></p><p v-if="game.players?.length"><strong>In the circle</strong> · {{ game.players.map(player => player.public_name || player.name).filter(Boolean).join(', ') }}</p><ul><li v-for="(player, pIndex) in game.players" :key="pIndex">{{ player.public_name || player.name || 'Seat ' + (pIndex + 1) }}<template v-if="player.character"> · {{ player.character }}</template><template v-if="player.died"> · died</template></li></ul><p>{{ game.notes }}</p></details></div></article></section>
    <p class="script-note">Curious how the game works? <a href="https://bloodontheclocktower.com/pages/how-to-play" target="_blank" rel="noopener noreferrer">Read the official guide ↗</a></p>
  </main>
</template>
<script setup>
useSeoMeta({ title: 'Blood on the Clocktower Sessions | Saujana BGC', description: 'Relive Saujana’s Blood on the Clocktower sessions, read Mika’s recaps, and find out when to join the next game night.' })
const config = useRuntimeConfig(), route = useRoute(), sessions = ref([]), photoUrls = ref({}), loading = ref(true), error = ref(''), shareNotice = ref('')
const headers = { apikey: config.public.supabaseKey, Authorization: 'Bearer ' + config.public.supabaseKey, 'Content-Type': 'application/json' }
const localDate = new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kuala_Lumpur',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())
const nextNight = computed(() => sessions.value.filter(x => x.session_date >= localDate).sort((a,b) => a.session_date.localeCompare(b.session_date))[0])
const pastSessions = computed(() => sessions.value.filter(x => x.session_date < localDate && x.games?.length))
const featured = computed(() => pastSessions.value.find(x => x.featured_game_id || x.recap || x.teaser))
const statistics = computed(() => ({ sessions: sessions.value.length, games: sessions.value.reduce((n,x) => n + (x.games?.length || 0),0), scripts: new Set(sessions.value.flatMap(x => x.games || []).map(x => x.script).filter(Boolean)).size }))
function formatDate(x) { return x ? new Date(x + 'T12:00:00').toLocaleDateString('en-MY',{day:'numeric',month:'long',year:'numeric'}) : 'Date to be announced' }
function cover(x) { const photos = (x.games || []).flatMap(g => g.photos || []).filter(p => p.approved); return (photos.find(p => p.cover) || photos[0])?.path }
async function loadArchive(){loading.value=true;error.value='';try{const response=await fetch(config.public.supabaseUrl+'/functions/v1/botc-archive',{method:'POST',headers,body:JSON.stringify({action:'public'})});const body=await response.json();if(!response.ok)throw new Error(body.error);sessions.value=body.sessions||[];photoUrls.value=body.photo_urls||{};await nextTick();const id=route.query.session;if(typeof id==='string')document.getElementById('session-'+id)?.scrollIntoView({behavior:'smooth'})}catch{error.value='We couldn’t load the session archive. Please try again.'}finally{loading.value=false}}
async function shareSession(session){const link=window.location.origin+'/only-blood-in-the-clocktower?session='+encodeURIComponent(session.id);try{await navigator.clipboard.writeText(link);shareNotice.value='Recap link copied.'}catch{shareNotice.value=link}}
onMounted(loadArchive)
</script>
<style scoped>
.share-button{min-height:44px;margin-top:8px;padding:10px 14px;border:1px solid var(--matcha-leaf);border-radius:6px;background:var(--matcha-leaf);color:white;font:inherit;font-weight:650;cursor:pointer}
.share-button:focus-visible{outline:3px solid var(--gold-leaf);outline-offset:3px}
.clocktower-page{width:min(960px,92%);margin:auto;padding:40px 0 80px;color:var(--clay-text)}h1{font:400 clamp(2.5rem,7vw,5rem)/1.05 var(--font-display);color:var(--matcha-leaf)}.page-eyebrow,.eyebrow{color:var(--gold-leaf);font-size:.73rem;letter-spacing:.12em;text-transform:uppercase}.intro{font:1.2rem/1.6 var(--font-display);color:var(--muted)}.next-night,.featured,.stats,.session-card{background:var(--white-pure);border:1px solid var(--line);border-radius:12px;padding:clamp(20px,4vw,34px);margin:20px 0}.next-night{display:flex;align-items:center;justify-content:space-between;gap:20px;background:var(--matcha-leaf);color:white}.next-night .eyebrow{color:#e2c995}.next-night h2,.featured h2,.archive h2,.stats h2{font:2rem var(--font-display);margin:4px 0;color:var(--matcha-leaf)}.next-night h2{color:white}.primary-link{background:#e2c995;color:#263d31;padding:14px 19px;border-radius:7px;text-decoration:none;font-weight:700;white-space:nowrap}.featured{display:grid;grid-template-columns:minmax(180px,.75fr) 1fr;gap:26px;align-items:center}.featured img{width:100%;aspect-ratio:4/3;object-fit:cover;border-radius:9px}.stat-row{display:flex;gap:40px}.stat-row div{display:grid}.stat-row strong{font:2rem var(--font-display);color:var(--matcha-leaf)}.stat-row span,.session-card p{color:var(--muted)}.session-card h3{font:1.55rem var(--font-display);color:var(--matcha-leaf)}.game-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:10px}.game-grid details{background:var(--surface-soft);padding:14px;border-radius:8px}.game-grid summary,summary{cursor:pointer;font-weight:650}.game-grid ul{padding-left:20px;font-size:.88rem}.script-note{text-align:center;color:var(--muted)}.script-note a{color:var(--matcha-leaf)}@media(max-width:650px){.clocktower-page{padding-top:20px}.next-night{align-items:flex-start;flex-direction:column}.featured{grid-template-columns:1fr}.stat-row{gap:20px}}
</style>
